async def get_db():
    pool = await asyncpg.create_pool(DSN, min_size=10)   # "works on my machine"
    try:
        yield pool
    finally:
        await pool.close()

@app.get("/orders/{id}")
async def get_order(id: int, db=Depends(get_db)):
    return await db.fetchrow("SELECT * FROM orders WHERE id=$1", id)

scenario.ru:
# Зависимость создаёт пул соединений — и в этом вся беда
async def get_db():
    pool = await asyncpg.create_pool(DSN, min_size=10)   # «на моей машине работает»
    try:
        yield pool
    finally:
        await pool.close()

@app.get("/orders/{id}")
async def get_order(id: int, db=Depends(get_db)):
    return await db.fetchrow("SELECT * FROM orders WHERE id=$1", id)
